WITH enriched AS (SELECT e.id, e.dept_id, e.manager_id, e.job_title, e.salary, e.hire_date, p.hire_date AS employee_hire_date, p.job_title AS employee_job_title FROM employees e JOIN employees p ON e.manager_id = p.id) SELECT s.id, s.manager_id, s.job_title, s.salary, s.employee_job_title, (SELECT SUM(x.salary) FROM employees x WHERE x.manager_id = s.manager_id) AS sum_employee_salary FROM enriched s ORDER BY employee_job_title DESC;
